handleSteps:
function* ({
  params,
  model,
  contextPruning
}) {
  const compaction = model === "deepseek/deepseek-v4-flash" && contextPruning ? {
    cacheExpiryMs: contextPruning.cacheExpiryMs,
    cacheExpiryMinTokens: contextPruning.cacheExpiryMinTokens
  } : { cacheExpiryMs: 30 * 60 * 1e3 };
  while (true) {
    yield {
      toolName: "spawn_agent_inline",
      input: {
        agent_type: "context-pruner",
        params: {
          maxContextLength: contextPruning?.maxContextLength ?? 4e5,
          ...params ?? {},
          ...compaction
        }
      },
      includeToolCall: false
    };
    const { stepsComplete } = yield "STEP";
    if (stepsComplete) break;
  }
}
